import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import test from 'node:test';
import { GoogleDriveReportStorageBoundary, LocalOnlyReportStorageAdapter, PDF_FONT_FALLBACKS, PDF_MIN_BODY_FONT_PT, applyPdfValidation, approvePdfArtifact, archiveEntryFromArtifact, assertPdfPublicModelSafe, buildDailyPdfViewModels, buildLiveDailyPdfViewModels, buildPeriodicPdfFoundations, canonicalReportFileName, compareArticlePdfConsistency, createGeneratedArtifact, markArtifactPublic, optionalQrTarget, pdfDownloadCta, reportLinkEdge, uploadApprovedArtifact, validatePdfHeader } from '../src/reports/pdf-production.js';
const now = '2026-10-02T10:00:00+09:00';
const daily = buildDailyPdfViewModels();
const ai = daily[0];
const us = daily[1];
const korea = daily[2];
const pass = { status: 'PASS', checks: { fileExists: true, nonZeroSize: true, validPdfSignature: true, pageCount: true, textExtraction: true, koreanText: true, motusTitle: true, issueDate: true, noInternalIds: true, noRawSecret: true, noLocalhost: true, noPlaceholder: true, noFixtureLabel: true, overflow: true, charts: true, sources: true, fontEmbedded: true, minimumBodyFontSize: true }, warnings: [], errors: [], extractedTextLength: 100, fontNames: ['MOTUS-KR'] };
const generated = () => createGeneratedArtifact(ai, 'data/reports/report.pdf', 1234, 1, now);
test('Sprint 4I builds three Daily PDF ViewModels from verified publication models', () => { assert.deepEqual(daily.map(item => item.reportType), ['AI_DAILY', 'US_MARKET_DAILY', 'KOREA_MARKET_DAILY']); assert.ok(daily.every(item => item.reviewState === 'PENDING' && item.sources.length && item.previewOnly === false)); });
test('Sprint 4I AI Daily PDF hierarchy contains required sections', () => { assert.deepEqual(ai.sections.map(item => item.title), ['오늘의 핵심', '주요 AI 이슈', '산업·기업 연결', '다음 확인사항']); assert.match(ai.displayTitle, /AI Intelligence/); });
test('Sprint 4I US Market PDF reuses four actual five-session charts', () => { assert.equal(us.charts.length, 4); assert.ok(us.charts.every(chart => chart.values.length === 5 && chart.labels.length === 5 && chart.sourceLabel)); assert.match(us.sections.map(item => item.title).join(' '), /VIX.*금리.*환율.*유가/); });
test('Sprint 4I Korea PDF includes market, flows and brokerage research without fake history', () => { assert.equal(korea.charts.length, 0); assert.match(korea.sections.map(item => item.title).join(' '), /투자자 수급/); assert.match(korea.sections.map(item => item.title).join(' '), /증권사 리서치/); });
test('Sprint 4I Weekly and Monthly foundations stay preview-only while HOLD', () => { const period = buildPeriodicPdfFoundations(); assert.equal(period.weekly.reportType, 'WEEKLY_INTELLIGENCE'); assert.equal(period.monthly.reportType, 'MONTHLY_INTELLIGENCE'); assert.equal(period.weekly.previewOnly, true); assert.equal(period.monthly.previewOnly, true); });
test('Sprint 4I canonical filenames are lowercase and filesystem-safe', () => { assert.equal(canonicalReportFileName('AI_DAILY', '2026-10-01'), 'motus-ai-daily-2026-10-01.pdf'); assert.equal(canonicalReportFileName('US_MARKET_DAILY', '2026-09-30'), 'motus-us-market-2026-09-30.pdf'); assert.equal(canonicalReportFileName('KOREA_MARKET_DAILY', '2026-09-30'), 'motus-korea-market-2026-09-30.pdf'); assert.match(canonicalReportFileName('WEEKLY_INTELLIGENCE', '2026-10-02', '2026-09-28'), /^motus-weekly-2026-w\d{2}\.pdf$/); assert.equal(canonicalReportFileName('MONTHLY_INTELLIGENCE', '2026-09-30'), 'motus-monthly-2026-09.pdf'); });
test('Sprint 4I validates PDF signature', () => { assert.equal(validatePdfHeader(Buffer.from('%PDF-1.7\n')), true); assert.equal(validatePdfHeader(Buffer.from('not pdf data')), false); });
test('Sprint 4I declares Korean system font fallbacks and minimum body size', () => { assert.deepEqual(PDF_FONT_FALLBACKS, ['Malgun Gothic', 'Noto Sans CJK KR', 'Arial Unicode MS']); assert.equal(PDF_MIN_BODY_FONT_PT, 8); });
test('Sprint 4I artifact fingerprints are stable and validation advances state', () => { const first = generated(), second = generated(); assert.equal(first.contentFingerprint, second.contentFingerprint); const validated = applyPdfValidation(first, pass); assert.equal(validated.state, 'VALIDATED'); assert.equal(validated.validationStatus, 'PASS'); });
test('Sprint 4I failed validation blocks distribution', () => { const failed = applyPdfValidation(generated(), { ...pass, status: 'FAIL', errors: ['koreanText'], checks: { ...pass.checks, koreanText: false } }); assert.equal(failed.state, 'FAILED'); assert.match(failed.failureReason, /koreanText/); });
test('Sprint 4I public model rejects internal ID, placeholder and localhost leakage', () => { assert.doesNotThrow(() => assertPdfPublicModelSafe(ai)); assert.throws(() => assertPdfPublicModelSafe({ ...ai, subtitle: 'claimId leaked' }), /internal ID/); assert.throws(() => assertPdfPublicModelSafe({ ...ai, subtitle: 'http://localhost/report' }), /non-production/); });
test('Sprint 4I Google Drive boundary remains NOT_CONFIGURED', async () => { const drive = new GoogleDriveReportStorageBoundary(); assert.equal(drive.state, 'NOT_CONFIGURED'); await assert.rejects(() => drive.uploadArtifact(generated()), /NOT_CONFIGURED/); assert.equal(await drive.getArtifact('x'), null); });
test('Sprint 4I upload requires validation and explicit human approval', async () => { const storage = new LocalOnlyReportStorageAdapter(); await assert.rejects(() => uploadApprovedArtifact(generated(), storage), /APPROVAL/); const approved = approvePdfArtifact(applyPdfValidation(generated(), pass), 'human', now); assert.equal(approved.state, 'UPLOAD_READY'); await assert.rejects(() => uploadApprovedArtifact(approved, storage), /STORAGE_NOT_CONFIGURED/); });
test('Sprint 4I PDF CTA requires published article and PUBLIC_AVAILABLE artifact', () => { const validated = applyPdfValidation(generated(), pass); assert.equal(pdfDownloadCta({ publicationState: 'PUBLISHED', artifact: validated }), null); const publicArtifact = { ...validated, state: 'PUBLIC_AVAILABLE', downloadUrl: 'https://cdn.motus.example/reports/a.pdf' }; assert.equal(pdfDownloadCta({ publicationState: 'DRAFT', artifact: publicArtifact }), null); assert.equal(pdfDownloadCta({ publicationState: 'PUBLISHED', artifact: publicArtifact }), publicArtifact.downloadUrl); });
test('Sprint 4I rejects invalid public PDF URLs and omits unverified QR', async () => { const storage = { provider: 'OBJECT_STORAGE', state: 'READY', async uploadArtifact() { return { provider: 'OBJECT_STORAGE', objectId: '1', downloadUrl: null }; }, async getArtifact() { return null; }, async validatePublicUrl() { return false; }, async revokePublicUrl() { } }; const uploaded = { ...generated(), state: 'UPLOADED', reviewState: 'APPROVED', storageProvider: 'OBJECT_STORAGE', storageObjectId: '1' }; await assert.rejects(() => markArtifactPublic(uploaded, storage, 'http://localhost/a.pdf'), /VALIDATION/); assert.equal(optionalQrTarget(null), null); assert.equal(optionalQrTarget('http://localhost/report'), null); assert.equal(optionalQrTarget('https://motusnova.blogspot.com/report'), 'https://motusnova.blogspot.com/report'); });
test('Sprint 4I article and PDF fingerprint mismatch becomes HOLD', () => { assert.deepEqual(compareArticlePdfConsistency({ articleSourceFingerprint: 'a', pdfSourceFingerprint: 'a', articleContentFingerprint: 'b', pdfContentFingerprint: 'b' }), { state: 'PASS', reason: null }); assert.deepEqual(compareArticlePdfConsistency({ articleSourceFingerprint: 'a', pdfSourceFingerprint: 'x', articleContentFingerprint: 'b', pdfContentFingerprint: 'b' }), { state: 'HOLD', reason: 'CONTENT_MISMATCH' }); });
test('Sprint 4I Reports Archive exposes only PUBLIC_AVAILABLE artifacts', () => { const validated = applyPdfValidation(generated(), pass); assert.equal(archiveEntryFromArtifact(validated, 'AI Report', null).state, 'PREVIEW_READY'); assert.equal(archiveEntryFromArtifact(validated, 'AI Report', null).downloadUrl, null); const published = { ...validated, state: 'PUBLIC_AVAILABLE', downloadUrl: 'https://cdn.motus.example/report.pdf' }; const entry = archiveEntryFromArtifact(published, 'AI Report', 'https://motusnova.blogspot.com/article'); assert.equal(entry.state, 'AVAILABLE'); assert.equal(entry.downloadUrl, published.downloadUrl); });
test('Sprint 4I search graph exposes REPORT_LINK only after public URL validation', () => { const validated = applyPdfValidation(generated(), pass); assert.equal(reportLinkEdge(validated, 'article:ai'), null); const published = { ...validated, state: 'PUBLIC_AVAILABLE', downloadUrl: 'https://cdn.motus.example/report.pdf' }; assert.deepEqual(reportLinkEdge(published, 'article:ai'), { fromPublicationId: 'article:ai', toPublicationId: published.artifactId, reason: 'REPORT_LINK' }); });
test('Sprint 4I Commerce and advertising are absent from PDF view models', () => { assert.ok(daily.every(item => item.commerce.enabled === false)); assert.doesNotMatch(JSON.stringify(daily), /affiliate|advertising|ad block/i); });
test('Sprint 4I review state remains independent and PENDING after local validation', () => { const validated = applyPdfValidation(generated(), pass); assert.equal(validated.reviewState, 'PENDING'); assert.equal(validated.state, 'VALIDATED'); });
test('Sprint 4I generated production artifacts are real validated PDFs with pending review', () => { for (const path of ['data/reports/daily/2026-09-29/ai', 'data/reports/daily/2026-09-30/us', 'data/reports/daily/2026-09-30/korea']) {
    assert.equal(existsSync(`${path}/report.pdf`), true);
    assert.equal(validatePdfHeader(readFileSync(`${path}/report.pdf`)), true);
    const artifact = JSON.parse(readFileSync(`${path}/artifact.json`, 'utf8'));
    const validation = JSON.parse(readFileSync(`${path}/validation.json`, 'utf8'));
    assert.equal(artifact.state, 'VALIDATED');
    assert.equal(artifact.reviewState, 'PENDING');
    assert.equal(artifact.downloadUrl, null);
    assert.equal(validation.status, 'PASS');
} });
test('live AI and U.S. PDF models preserve production facts, chart dates, sources and Commerce off', () => { const live = buildLiveDailyPdfViewModels(); assert.deepEqual(live.map(item => item.issueDate), ['2026-10-05', '2026-10-05']); assert.ok(live.every(item => item.sources.length && item.commerce.enabled === false && item.reviewState === 'PENDING')); const us = live.find(item => item.reportType === 'US_MARKET_DAILY'); assert.equal(us.charts.length, 4); assert.ok(us.charts.every(chart => chart.labels[0] === '2026-09-29' && chart.labels.at(-1) === '2026-10-05')); assert.equal(us.charts[0]?.latestValue, '7,773.95'); });
